      AiInput_ai_input_05,
      "\"use client\";\n\nimport * as React from \"react\";\nimport { ArrowUp } from \"lucide-react\";\nimport { cn } from \"@/lib/utils\";\nimport { useAutoResizeTextarea } from \"@/hooks/use-auto-resize-textarea\";\n\ninterface AIInput05Props {\n  value?: string;\n  onChange?: (value: string) => void;\n  onSubmit?: (value: string) => void;\n  label?: string;\n  disabled?: boolean;\n  className?: string;\n}\n\nexport function AIInput05({\n  value: controlledValue,\n  onChange,\n  onSubmit,\n  label = \"Your message\",\n  disabled = false,\n  className,\n}: AIInput05Props) {\n  const [internalValue, setInternalValue] = React.useState(\"\");\n  const [isFocused, setIsFocused] = React.useState(false);\n  const value = controlledValue ?? internalValue;\n  const setValue = onChange ?? setInternalValue;\n\n  const { textareaRef, adjustHeight } = useAutoResizeTextarea({\n    minHeight: 64,\n    maxHeight: 200,\n  });\n\n  const handleSubmit = () => {\n    if (!value.trim() || disabled) return;\n    onSubmit?.(value);\n    setValue(\"\");\n    adjustHeight(true);\n  };\n\n  const isActive = isFocused || value.length > 0;\n\n  return (\n    <div className={cn(\"w-full max-w-xl mx-auto\", className)}>\n      <div\n        className={cn(\n          \"relative rounded-2xl bg-white dark:bg-zinc-950\",\n          \"transition-all duration-300\",\n          disabled && \"opacity-50\",\n        )}\n      >\n        {/* Animated border */}\n        <div\n          className={cn(\n            \"absolute inset-0 rounded-2xl pointer-events-none\",\n            \"border-2 transition-all duration-300\",\n            isFocused\n              ? \"border-zinc-900 dark:border-zinc-100\"\n              : \"border-zinc-200 dark:border-zinc-800\",\n          )}\n        />\n\n        {/* Label */}\n        <label\n          className={cn(\n            \"absolute left-4 pointer-events-none z-10\",\n            \"transition-all duration-200 ease-out\",\n            \"text-zinc-500 dark:text-zinc-400\",\n            isActive\n              ? [\n                  \"top-2.5 text-[11px] font-semibold tracking-wider uppercase\",\n                  isFocused\n                    ? \"text-zinc-900 dark:text-zinc-100\"\n                    : \"text-zinc-500 dark:text-zinc-400\",\n                ]\n              : [\"top-1/2 -translate-y-1/2 text-[15px]\"],\n          )}\n        >\n          {label}\n        </label>\n\n        <textarea\n          ref={textareaRef}\n          disabled={disabled}\n          value={value}\n          onFocus={() => setIsFocused(true)}\n          onBlur={() => setIsFocused(false)}\n          onChange={(e) => {\n            setValue(e.target.value);\n            adjustHeight();\n          }}\n          onKeyDown={(e) => {\n            if (e.key === \"Enter\" && !e.shiftKey) {\n              e.preventDefault();\n              handleSubmit();\n            }\n          }}\n          rows={1}\n          className={cn(\n            \"w-full resize-none bg-transparent\",\n            \"pr-14 outline-none border-none ring-0\",\n            \"text-[15px] text-zinc-800 dark:text-zinc-100\",\n            \"min-h-[64px] max-h-[200px]\",\n            \"leading-relaxed transition-all duration-200\",\n            isActive ? \"pt-7 pb-3 pl-4\" : \"py-5 pl-4\",\n          )}\n        />\n\n        <button\n          type=\"button\"\n          disabled={!value.trim() || disabled}\n          onClick={handleSubmit}\n          className={cn(\n            \"absolute right-2.5 bottom-2.5\",\n            \"flex items-center justify-center size-9 rounded-xl\",\n            \"transition-all duration-200\",\n            value.trim()\n              ? \"bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 hover:opacity-90 active:scale-95\"\n              : \"bg-zinc-100 dark:bg-zinc-800 text-zinc-300 dark:text-zinc-600 cursor-not-allowed\",\n          )}\n        >\n          <ArrowUp className=\"size-4\" />\n        </button>\n      </div>\n    </div>\n  );\n}\n",
