      Alert_alert_16,
      "\"use client\";\n\nimport { useState } from \"react\";\nimport { Activity, X, MoreHorizontal } from \"lucide-react\";\nimport { cn } from \"@/lib/utils\";\n\ninterface ActivityItem {\n  id: string;\n  user: string;\n  avatar: string;\n  action: string;\n  target: string;\n  time: string;\n}\n\ninterface Alert16Props {\n  title?: string;\n  activities?: ActivityItem[];\n  onViewAll?: () => void;\n  onDismiss?: () => void;\n  className?: string;\n}\n\nconst defaultActivities: ActivityItem[] = [\n  {\n    id: \"1\",\n    user: \"Sarah\",\n    avatar: \"S\",\n    action: \"commented on\",\n    target: \"Design Review\",\n    time: \"2m ago\",\n  },\n  {\n    id: \"2\",\n    user: \"Mike\",\n    avatar: \"M\",\n    action: \"merged\",\n    target: \"PR #234\",\n    time: \"15m ago\",\n  },\n  {\n    id: \"3\",\n    user: \"Emma\",\n    avatar: \"E\",\n    action: \"completed\",\n    target: \"Dashboard UI\",\n    time: \"1h ago\",\n  },\n];\n\nexport default function Alert16({\n  title = \"Recent Activity\",\n  activities = defaultActivities,\n  onViewAll,\n  onDismiss,\n  className,\n}: Alert16Props) {\n  const [isVisible, setIsVisible] = useState(true);\n  const [isExiting, setIsExiting] = useState(false);\n\n  const handleDismiss = () => {\n    setIsExiting(true);\n    setTimeout(() => {\n      setIsVisible(false);\n      onDismiss?.();\n    }, 200);\n  };\n\n  if (!isVisible) return null;\n\n  return (\n    <div className={cn(\"w-full max-w-sm mx-auto\", className)}>\n      <div\n        className={cn(\n          \"relative rounded-xl overflow-hidden\",\n          \"bg-white dark:bg-zinc-900\",\n          \"border border-zinc-200 dark:border-zinc-800\",\n          \"shadow-lg shadow-zinc-200/50 dark:shadow-zinc-950/50\",\n          \"transition-all duration-200\",\n          isExiting && \"opacity-0 scale-95\",\n        )}\n        role=\"log\"\n        aria-label={title}\n      >\n        <div className=\"flex items-center justify-between px-4 py-3 border-b border-zinc-100 dark:border-zinc-800\">\n          <div className=\"flex items-center gap-2\">\n            <Activity className=\"h-4 w-4 text-zinc-500 dark:text-zinc-400\" />\n            <h3 className=\"text-sm font-semibold text-zinc-900 dark:text-zinc-100\">{title}</h3>\n          </div>\n          <button\n            onClick={handleDismiss}\n            className={cn(\n              \"p-1 rounded-md\",\n              \"text-zinc-400 hover:text-zinc-600 dark:text-zinc-500 dark:hover:text-zinc-300\",\n              \"hover:bg-zinc-100 dark:hover:bg-zinc-800\",\n              \"transition-colors duration-150\",\n              \"focus:outline-none focus:ring-2 focus:ring-zinc-400\",\n            )}\n            aria-label=\"Dismiss\"\n          >\n            <X className=\"h-4 w-4\" />\n          </button>\n        </div>\n\n        <div className=\"divide-y divide-zinc-100 dark:divide-zinc-800\">\n          {activities.map((activity) => (\n            <div\n              key={activity.id}\n              className={cn(\n                \"flex items-center gap-3 px-4 py-3\",\n                \"hover:bg-zinc-50 dark:hover:bg-zinc-800/50\",\n                \"transition-colors duration-150\",\n              )}\n            >\n              <div\n                className={cn(\n                  \"flex-shrink-0 w-8 h-8 rounded-full\",\n                  \"flex items-center justify-center\",\n                  \"bg-gradient-to-br from-zinc-100 to-zinc-200 dark:from-zinc-700 dark:to-zinc-800\",\n                  \"text-xs font-semibold text-zinc-700 dark:text-zinc-300\",\n                )}\n              >\n                {activity.avatar}\n              </div>\n\n              <div className=\"flex-1 min-w-0\">\n                <p className=\"text-sm text-zinc-700 dark:text-zinc-300 truncate\">\n                  <span className=\"font-medium text-zinc-900 dark:text-zinc-100\">\n                    {activity.user}\n                  </span>{\" \"}\n                  {activity.action}{\" \"}\n                  <span className=\"font-medium text-zinc-900 dark:text-zinc-100\">\n                    {activity.target}\n                  </span>\n                </p>\n                <p className=\"text-[11px] text-zinc-500 dark:text-zinc-500\">{activity.time}</p>\n              </div>\n\n              <button\n                className={cn(\n                  \"flex-shrink-0 p-1 rounded-md opacity-0 group-hover:opacity-100\",\n                  \"text-zinc-400 hover:text-zinc-600 dark:text-zinc-500 dark:hover:text-zinc-300\",\n                  \"hover:bg-zinc-100 dark:hover:bg-zinc-800\",\n                  \"transition-all duration-150\",\n                  \"focus:outline-none focus:opacity-100 focus:ring-2 focus:ring-zinc-400\",\n                )}\n                aria-label=\"More options\"\n              >\n                <MoreHorizontal className=\"h-4 w-4\" />\n              </button>\n            </div>\n          ))}\n        </div>\n\n        <div className=\"px-4 py-2.5 bg-zinc-50 dark:bg-zinc-800/50 border-t border-zinc-100 dark:border-zinc-800\">\n          <button\n            onClick={onViewAll}\n            className={cn(\n              \"w-full py-1.5 text-xs font-medium text-center rounded-lg\",\n              \"text-zinc-600 dark:text-zinc-400\",\n              \"hover:bg-zinc-100 dark:hover:bg-zinc-700\",\n              \"transition-colors duration-150\",\n              \"focus:outline-none focus:ring-2 focus:ring-zinc-400\",\n            )}\n          >\n            View all activity\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
