      "\"use client\";\n\nimport { useState } from \"react\";\nimport { Users, X, Plus, Check, Search } from \"lucide-react\";\nimport { cn } from \"@/lib/utils\";\n\ninterface TeamMember {\n  id: string;\n  name: string;\n  email: string;\n  avatar: string;\n  role: string;\n  online: boolean;\n}\n\ninterface Alert20Props {\n  title?: string;\n  description?: string;\n  members?: TeamMember[];\n  onInvite?: (email: string) => void;\n  onDismiss?: () => void;\n  className?: string;\n}\n\nconst defaultMembers: TeamMember[] = [\n  {\n    id: \"1\",\n    name: \"Alex Chen\",\n    email: \"alex@company.com\",\n    avatar: \"AC\",\n    role: \"Owner\",\n    online: true,\n  },\n  {\n    id: \"2\",\n    name: \"Sarah Kim\",\n    email: \"sarah@company.com\",\n    avatar: \"SK\",\n    role: \"Editor\",\n    online: true,\n  },\n  {\n    id: \"3\",\n    name: \"Mike Johnson\",\n    email: \"mike@company.com\",\n    avatar: \"MJ\",\n    role: \"Viewer\",\n    online: false,\n  },\n];\n\nexport default function Alert20({\n  title = \"Team Collaboration\",\n  description = \"Manage who has access to this project.\",\n  members = defaultMembers,\n  onInvite,\n  onDismiss,\n  className,\n}: Alert20Props) {\n  const [isVisible, setIsVisible] = useState(true);\n  const [isExiting, setIsExiting] = useState(false);\n  const [email, setEmail] = useState(\"\");\n  const [isInviting, setIsInviting] = useState(false);\n  const [inviteSent, setInviteSent] = useState(false);\n  const [searchQuery, setSearchQuery] = useState(\"\");\n\n  const filteredMembers = members.filter(\n    (member) =>\n      member.name.toLowerCase().includes(searchQuery.toLowerCase()) ||\n      member.email.toLowerCase().includes(searchQuery.toLowerCase()),\n  );\n\n  const handleDismiss = () => {\n    setIsExiting(true);\n    setTimeout(() => {\n      setIsVisible(false);\n      onDismiss?.();\n    }, 200);\n  };\n\n  const handleInvite = (e: React.FormEvent) => {\n    e.preventDefault();\n    if (!email.trim()) return;\n\n    setIsInviting(true);\n    setTimeout(() => {\n      setIsInviting(false);\n      setInviteSent(true);\n      onInvite?.(email);\n      setTimeout(() => {\n        setInviteSent(false);\n        setEmail(\"\");\n      }, 2000);\n    }, 1000);\n  };\n\n  if (!isVisible) return null;\n\n  return (\n    <div className={cn(\"w-full max-w-md mx-auto\", className)}>\n      <div\n        className={cn(\n          \"relative rounded-xl overflow-hidden\",\n          \"bg-white dark:bg-zinc-900\",\n          \"border border-zinc-200 dark:border-zinc-800\",\n          \"shadow-xl shadow-zinc-200/50 dark:shadow-zinc-950/50\",\n          \"transition-all duration-200\",\n          isExiting && \"opacity-0 scale-95\",\n        )}\n        role=\"dialog\"\n        aria-labelledby=\"team-title\"\n      >\n        <div className=\"p-5 border-b border-zinc-100 dark:border-zinc-800\">\n          <div className=\"flex items-start justify-between gap-4\">\n            <div className=\"flex items-start gap-3\">\n              <div className=\"flex-shrink-0 p-2.5 rounded-xl bg-gradient-to-br from-blue-500 to-indigo-600 shadow-lg shadow-blue-500/25\">\n                <Users className=\"h-5 w-5 text-white\" />\n              </div>\n\n              <div>\n                <h3\n                  id=\"team-title\"\n                  className=\"text-base font-semibold text-zinc-900 dark:text-zinc-100\"\n                >\n                  {title}\n                </h3>\n                <p className=\"mt-0.5 text-sm text-zinc-600 dark:text-zinc-400\">{description}</p>\n              </div>\n            </div>\n\n            <button\n              onClick={handleDismiss}\n              className={cn(\n                \"flex-shrink-0 p-1 rounded-md\",\n                \"text-zinc-400 hover:text-zinc-600 dark:text-zinc-500 dark:hover:text-zinc-300\",\n                \"hover:bg-zinc-100 dark:hover:bg-zinc-800\",\n                \"transition-colors duration-150\",\n                \"focus:outline-none focus:ring-2 focus:ring-zinc-400\",\n              )}\n              aria-label=\"Close\"\n            >\n              <X className=\"h-4 w-4\" />\n            </button>\n          </div>\n\n          <form onSubmit={handleInvite} className=\"mt-4\">\n            <div className=\"flex gap-2\">\n              <input\n                type=\"email\"\n                value={email}\n                onChange={(e) => setEmail(e.target.value)}\n                placeholder=\"Enter email to invite...\"\n                className={cn(\n                  \"flex-1 px-3 py-2 text-sm rounded-lg\",\n                  \"bg-zinc-50 dark:bg-zinc-800\",\n                  \"border border-zinc-200 dark:border-zinc-700\",\n                  \"text-zinc-900 dark:text-zinc-100\",\n                  \"placeholder:text-zinc-400 dark:placeholder:text-zinc-500\",\n                  \"focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent\",\n                )}\n              />\n              <button\n                type=\"submit\"\n                disabled={isInviting || inviteSent || !email.trim()}\n                className={cn(\n                  \"inline-flex items-center gap-1.5 px-4 py-2 text-sm font-medium rounded-lg\",\n                  \"transition-all duration-150\",\n                  \"disabled:opacity-50 disabled:cursor-not-allowed\",\n                  \"focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2\",\n                  \"dark:focus:ring-offset-zinc-900\",\n                  inviteSent\n                    ? \"bg-emerald-600 text-white\"\n                    : \"bg-blue-600 hover:bg-blue-700 text-white\",\n                )}\n              >\n                {isInviting ? (\n                  <div className=\"h-4 w-4 border-2 border-white/30 border-t-white rounded-full animate-spin\" />\n                ) : inviteSent ? (\n                  <>\n                    <Check className=\"h-4 w-4\" />\n                    Sent\n                  </>\n                ) : (\n                  <>\n                    <Plus className=\"h-4 w-4\" />\n                    Invite\n                  </>\n                )}\n              </button>\n            </div>\n          </form>\n        </div>\n\n        <div className=\"px-5 py-3 border-b border-zinc-100 dark:border-zinc-800\">\n          <div className=\"relative\">\n            <Search className=\"absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-400\" />\n            <input\n              type=\"text\"\n              value={searchQuery}\n              onChange={(e) => setSearchQuery(e.target.value)}\n              placeholder=\"Search members...\"\n              className={cn(\n                \"w-full pl-9 pr-3 py-2 text-sm rounded-lg\",\n                \"bg-zinc-50 dark:bg-zinc-800\",\n                \"border border-zinc-200 dark:border-zinc-700\",\n                \"text-zinc-900 dark:text-zinc-100\",\n                \"placeholder:text-zinc-400 dark:placeholder:text-zinc-500\",\n                \"focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent\",\n              )}\n            />\n          </div>\n        </div>\n\n        <div className=\"max-h-64 overflow-y-auto\">\n          <div className=\"divide-y divide-zinc-100 dark:divide-zinc-800\">\n            {filteredMembers.map((member) => (\n              <div\n                key={member.id}\n                className={cn(\n                  \"flex items-center gap-3 px-5 py-3\",\n                  \"hover:bg-zinc-50 dark:hover:bg-zinc-800/50\",\n                  \"transition-colors duration-150\",\n                )}\n              >\n                <div className=\"relative flex-shrink-0\">\n                  <div\n                    className={cn(\n                      \"w-9 h-9 rounded-full flex items-center justify-center\",\n                      \"bg-gradient-to-br from-zinc-100 to-zinc-200 dark:from-zinc-700 dark:to-zinc-800\",\n                      \"text-xs font-semibold text-zinc-700 dark:text-zinc-300\",\n                    )}\n                  >\n                    {member.avatar}\n                  </div>\n                  <div\n                    className={cn(\n                      \"absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full border-2 border-white dark:border-zinc-900\",\n                      member.online ? \"bg-emerald-500\" : \"bg-zinc-300 dark:bg-zinc-600\",\n                    )}\n                  />\n                </div>\n\n                <div className=\"flex-1 min-w-0\">\n                  <p className=\"text-sm font-medium text-zinc-900 dark:text-zinc-100 truncate\">\n                    {member.name}\n                  </p>\n                  <p className=\"text-xs text-zinc-500 dark:text-zinc-400 truncate\">\n                    {member.email}\n                  </p>\n                </div>\n\n                <span\n                  className={cn(\n                    \"flex-shrink-0 px-2 py-1 text-[10px] font-medium uppercase tracking-wide rounded-full\",\n                    member.role === \"Owner\"\n                      ? \"bg-amber-100 dark:bg-amber-900/50 text-amber-700 dark:text-amber-300\"\n                      : member.role === \"Editor\"\n                        ? \"bg-blue-100 dark:bg-blue-900/50 text-blue-700 dark:text-blue-300\"\n                        : \"bg-zinc-100 dark:bg-zinc-800 text-zinc-600 dark:text-zinc-400\",\n                  )}\n                >\n                  {member.role}\n                </span>\n              </div>\n            ))}\n          </div>\n        </div>\n\n        <div className=\"px-5 py-3 bg-zinc-50 dark:bg-zinc-800/30 border-t border-zinc-100 dark:border-zinc-800\">\n          <p className=\"text-xs text-center text-zinc-500 dark:text-zinc-400\">\n            {members.length} team member{members.length !== 1 && \"s\"} •{\" \"}\n            {members.filter((m) => m.online).length} online\n          </p>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
      { previewClassName: "min-h-[120px] w-full max-w-lg" }
