      "\"use client\";\nimport { Calendar, Sparkles, Code2, ExternalLink, Share2 } from \"lucide-react\";\nimport Image from \"next/image\";\nimport { Button } from \"@/components/ui/button\";\nimport { cn } from \"@/lib/utils\";\n\ninterface Skill {\n  name: string;\n  level: number;\n}\n\ninterface Card02Props {\n  name?: string;\n  role?: string;\n  image?: string;\n  status?: string;\n  skills?: Skill[];\n  portfolio?: string;\n}\n\nconst defaultProfile = {\n  name: \"Eugene K\",\n  role: \"Senior Developer\",\n  image:\n    \"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQCYy_Pjw0UWMPSmVN7lL5yhod-0OhxDmeT4g&s\",\n  status: \"Open to Work\",\n  skills: [\n    { name: \"Frontend\", level: 5 },\n    { name: \"Backend\", level: 4 },\n    { name: \"DevOps\", level: 4 },\n  ],\n  portfolio: \"github.com/alexchen\",\n} satisfies Required<Card02Props>;\n\nexport default function Card_25({\n  name = defaultProfile.name,\n  role = defaultProfile.role,\n  image = defaultProfile.image,\n  status = defaultProfile.status,\n  skills = defaultProfile.skills,\n  portfolio = defaultProfile.portfolio,\n}: Card02Props = defaultProfile) {\n  return (\n    <div className=\"w-full max-w-xs mx-auto\">\n      <div\n        className={cn(\n          \"relative overflow-hidden\",\n          \"bg-white/50 dark:bg-zinc-900/50\",\n          \"backdrop-blur-xl\",\n          \"border border-zinc-200/50 dark:border-zinc-800/50\",\n          \"rounded-2xl\",\n          \"transition-all duration-300\",\n          \"hover:shadow-xl hover:shadow-zinc-200/20 dark:hover:shadow-zinc-900/20\",\n          \"hover:border-zinc-300/50 dark:hover:border-zinc-700/50\",\n        )}\n      >\n        <div className=\"p-5\">\n          <div className=\"flex items-center gap-4\">\n            <div className=\"relative group\">\n              <div\n                className={cn(\n                  \"w-16 h-16 rounded-xl overflow-hidden\",\n                  \"ring-2 ring-zinc-100 dark:ring-zinc-800\",\n                )}\n              >\n                <Image src={image} alt={name} width={64} height={64} className=\"object-cover\" />\n              </div>\n            </div>\n\n            <div className=\"flex-1\">\n              <h3 className=\"text-base font-semibold text-zinc-900 dark:text-zinc-100\">{name}</h3>\n              <p className=\"text-sm text-zinc-500 dark:text-zinc-400 mb-0.5\">{role}</p>\n              <div\n                className={cn(\n                  \"inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg\",\n                  \"bg-emerald-50 dark:bg-emerald-900/20\",\n                  \"text-emerald-600 dark:text-emerald-400\",\n                  \"text-xs font-medium\",\n                )}\n              >\n                <Calendar className=\"w-3 h-3\" />\n                {status}\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div className=\"px-5 pb-5\">\n          <div className=\"space-y-2.5\">\n            {skills?.map((skill) => (\n              <div\n                key={skill.name}\n                className={cn(\n                  \"flex items-center gap-3\",\n                  \"p-2 rounded-xl\",\n                  \"bg-zinc-50 dark:bg-zinc-800/50\",\n                  \"hover:bg-zinc-100 dark:hover:bg-zinc-800\",\n                  \"transition-colors duration-200\",\n                )}\n              >\n                <Code2 className=\"w-4 h-4 text-zinc-900 dark:text-zinc-100\" />\n                <div className=\"flex-1\">\n                  <div className=\"flex items-center justify-between text-sm mb-1.5\">\n                    <span className=\"text-zinc-700 dark:text-zinc-300 font-medium\">\n                      {skill.name}\n                    </span>\n                  </div>\n                  <div className=\"flex gap-1\">\n                    {[...Array(5)].map((_, i) => (\n                      <div\n                        key={i}\n                        className={cn(\n                          \"h-1 rounded-full flex-1\",\n                          i < skill.level\n                            ? \"bg-zinc-900 dark:bg-zinc-100\"\n                            : \"bg-zinc-200 dark:bg-zinc-700\",\n                        )}\n                      />\n                    ))}\n                  </div>\n                </div>\n              </div>\n            ))}\n          </div>\n        </div>\n\n        <div className=\"px-5 pb-5 flex gap-2 items-center\">\n          <Button\n            variant=\"default\"\n            size=\"sm\"\n            className={cn(\n              \"w-full\",\n              \"bg-zinc-900 dark:bg-zinc-100\",\n              \"hover:bg-zinc-700 dark:hover:bg-zinc-300\",\n              \"text-white dark:text-zinc-900\",\n              \"shadow-xs\",\n            )}\n          >\n            <ExternalLink className=\"w-4 h-4 mr-2\" />\n            View Portfolio\n          </Button>\n          <Button\n            variant=\"ghost\"\n            className=\"flex items-center gap-1.5 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-lg p-1.5\"\n          >\n            <Share2 className=\"w-4 h-4 text-zinc-900 dark:text-zinc-100\" />\n            <span className=\"text-sm text-zinc-900 dark:text-zinc-100\">Share</span>\n          </Button>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
